import { basename } from "node:path"

/** The address a pinned client refused. */
export class EgressAddressError extends Error {
  readonly _tag = "EgressAddressError"
  constructor(readonly address: string) {
    super(address)
  }
}

export const pinnedClient = (host: string): string => {
  const address = basename(host)
  if (address === "blocked") throw new EgressAddressError(address)
  return address
}

export const refused = (error: unknown): boolean => error instanceof EgressAddressError

import { readFileSync } from "node:fs"
import * as Lib from "./lib.ts"

/** How bad a seeded bug is. */
export const Severity = Lib.literals("low", "high")
export type Severity = typeof Severity.Type

export const readSeverity = (path: string): Severity => Severity.decode(readFileSync(path, "utf8"))

export const worst = (a: Severity, b: Severity): Severity => (a === "high" || b === "high" ? "high" : "low")

import { readFileSync } from "node:fs"
import * as Lib from "./lib.ts"

export const Issue = Lib.literals("open", "closed")
export type Item = { readonly state: typeof Issue.Type }

export const load = (path: string): Item => ({ state: Issue.decode(readFileSync(path, "utf8")) })
export const closed = (item: Item): boolean => item.state === "closed"

import { readFileSync } from "node:fs"

/** Reads files for the flow. */
export const layer = {
  read: (path: string): string => readFileSync(path, "utf8"),
}

export const label = (name: string): string => `layer:${name}`
